+			headSha: "ABCDEF1234567890",
+		});
+
+		expect(tag).toBe("1.2.3-pr.42.abcdef123456");
+		expect(tag.length).toBeLessThanOrEqual(MAX_WORKER_PREVIEW_TAG_LENGTH);
+	});
